  setTimeout(() => {
    notifications.push({
      title: 'HYDRA is online',
      body: hour >= 23 || hour < 6 ? 'Quiet hours. I will keep the lights low.' : 'Offline core ready. Press Ctrl+K to ask anything.',
      tone: 'system',
      icon: 'shield',
      silent: true,
    });
  }, 900);

