      value: state.aiModel,
      placeholder: state.aiProvider === 'openai' ? 'gpt-4o-mini' : state.aiProvider === 'gemini' ? 'gemini-2.0-flash' : 'llama3.2',
      onInput: (v) => settings.set({ aiModel: v.trim() }),
